<?php
require __DIR__.'/inc/core.php';
auth();
require_once __DIR__.'/inc/survey-operations.php';
$id=max(0,(int)($_GET['id']??0));
if(!$id){http_response_code(400);exit('Geçersiz ekspertiz numarası.');}
$q=db()->prepare('SELECT s.*,c.name customer_name,c.phone customer_phone,c.email customer_email FROM ek_surveys s JOIN customers c ON c.id=s.customer_id WHERE s.id=?');
$q->execute([$id]);$survey=$q->fetch(PDO::FETCH_ASSOC);
if(!$survey){http_response_code(404);exit('Ekspertiz bulunamadı.');}
if(!ekAdmin() && (int)$survey['assigned_user_id']!==(int)($_SESSION['uid']??0)){http_response_code(403);exit('Erişim yetkiniz yok.');}
$q=db()->prepare('SELECT room,item_name,quantity,unit_volume,notes FROM ek_survey_items WHERE survey_id=? ORDER BY room,id');$q->execute([$id]);$items=$q->fetchAll(PDO::FETCH_ASSOC);
$rooms=[];$sum=0.0;$pieces=0;
foreach($items as $i){$r=$i['room'];if(!isset($rooms[$r]))$rooms[$r]=['items'=>[],'volume'=>0,'pieces'=>0];$v=(int)$i['quantity']*(float)$i['unit_volume'];$rooms[$r]['items'][]=$i;$rooms[$r]['volume']+=$v;$rooms[$r]['pieces']+=(int)$i['quantity'];$sum+=$v;$pieces+=(int)$i['quantity'];}
header('Cache-Control: private, no-store, max-age=0');header('X-Content-Type-Options: nosniff');
function svEsc($v){return htmlspecialchars((string)($v??''),ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function svNum($n){return number_format((float)$n,2,',','.');}
$site=svOpsReady(db())?svOpsMeta(db(),$id)['fields']:[];
